solution:
const map = new Map([["name", "Hariom"], ["age", 25], ["city", "Jaipur"]])
const obj = Object.fromEntries(map)
const backToMap = new Map(Object.entries(obj))
return {
  obj: obj,
  mapSize: backToMap.size
}
